# Returns the logged-in user's API key + secret for token auth (NOT guest).
# Lets the mobile app switch from the 36h-expiring session cookie to a
# non-expiring token. Called once after password login; rotates the secret
# each call, so call it only at login bootstrap / on 401 recovery.
user = frappe.session.user
try:
    if not user or user == 'Guest':
        frappe.response['data'] = {'error': 'Not authenticated.'}
    else:
        u = frappe.get_doc('User', user)
        key = u.api_key
        if not key:
            key = frappe.utils.generate_hash(length=15)
            u.api_key = key
        secret = frappe.utils.generate_hash(length=15)
        u.api_secret = secret
        u.save(ignore_permissions=True)
        frappe.db.commit()
        frappe.response['data'] = {'api_key': key, 'api_secret': secret, 'user': user}
except Exception as e:
    frappe.log_error('productionGetApiCredentials error: ' + str(e))
    frappe.response['data'] = {'error': str(e)}
